import pyomo.environ as pyo

DATA = {
    "departments": ["X", "Y", "Z"],
    "total_budget": 1000,          # total budget must equal this exactly
    "x_minus_y_min": 200,          # X must exceed Y by at least this
    "z_max": 300,                  # Z upper bound
    "unit_cost": {"X": 50, "Y": 30, "Z": 20},  # cost per unit allocated
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.I = pyo.Set(initialize=d["departments"], ordered=True)

    # --- Variables ---
    def alloc_bounds(m, i):
        if i == "Z":
            return (0, d["z_max"])
        return (0, None)

    model.alloc = pyo.Var(
        model.I,
        domain=pyo.NonNegativeIntegers,
        bounds=alloc_bounds,
    )

    # --- Objective: minimise total cost ---
    def obj_rule(m):
        return sum(d["unit_cost"][i] * m.alloc[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Constraint: total budget exactly equals the allocation ---
    def total_budget_rule(m):
        return sum(m.alloc[i] for i in m.I) == d["total_budget"]

    model.total_budget = pyo.Constraint(rule=total_budget_rule)

    # --- Constraint: X receives at least 200 more than Y ---
    def x_over_y_rule(m):
        return m.alloc["X"] - m.alloc["Y"] >= d["x_minus_y_min"]

    model.x_over_y = pyo.Constraint(rule=x_over_y_rule)

    return model


